// checks StepResult.response.messages of the second step of a two-step generateText run
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  let ai;
  try { ai = require("ai"); } catch (e) {
    const { pathToFileURL } = require("url");
    ai = await import(pathToFileURL(require.resolve("ai")).href);
  }
  if (ai && !ai.generateText && ai.default) ai = ai.default;
  const usage = { inputTokens: { total: 1, noCache: 1, cacheRead: 0, cacheWrite: 0 }, outputTokens: { total: 1, text: 1, reasoning: 0 } };
  let calls = 0;
  const model = {
    specificationVersion: "v3", provider: "mock", modelId: "mock", supportedUrls: {},
    async doGenerate() {
      calls++;
      const content = calls === 1
        ? [{ type: "tool-call", toolCallId: "c1", toolName: "echo", input: JSON.stringify({ x: "hi" }) }]
        : [{ type: "text", text: "done" }];
      return { content, finishReason: { unified: calls === 1 ? "tool-calls" : "stop", raw: undefined }, usage, warnings: [] };
    },
    async doStream() { throw new Error("not used"); },
  };
  const tools = { echo: { inputSchema: ai.jsonSchema({ type: "object", properties: { x: { type: "string" } }, required: ["x"] }), execute: async ({ x }) => "echo " + x } };
  const r = await ai.generateText({ model, prompt: "hi", tools, stopWhen: ai.stepCountIs(5) });
  if (r.steps.length !== 2) broken("expected 2 steps, got " + r.steps.length);
  const roles = r.steps[1].response.messages.map(m => m.role).join(",");
  if (roles === "assistant,tool,assistant") symptom("second step response.messages also holds the first step's messages (" + roles + ")");
  if (roles !== "assistant") broken("unexpected second step response.messages roles: " + roles);
  console.log("OK: second step response.messages holds only that step's message");
})().catch(e => broken(String((e && e.stack) || e)));

